helpers=r'''  private LinearLayout pair(String l1,String a1,String l2,String a2){LinearLayout r=new LinearLayout(this);Button b1=blue(l1),b2=blue(l2);b1.setOnClickListener(v->mobileAction(a1,"","",0));b2.setOnClickListener(v->mobileAction(a2,"","",0));r.addView(b1,new LinearLayout.LayoutParams(0,dp(48),1));r.addView(b2,new LinearLayout.LayoutParams(0,dp(48),1));return r;}
  private Button redButton(String s){Button b=new Button(this);b.setAllCaps(false);b.setText(s);b.setTextColor(Color.WHITE);b.setTypeface(null,Typeface.BOLD);b.setBackground(round(Color.rgb(177,43,43),1,Color.rgb(238,75,75),10));return b;}
  private void mobileAction(String action,String target,String text,int value){if(!server.equals("AC3")){toast("This direct control is staged on AC3 first.");return;}if(!ready())return;setBusy(true,"SENDING");io.submit(()->{try{JSONObject j=new JSONObject();j.put("action",action);j.put("actor",login);j.put("target",target==null?"":target);j.put("text",text==null?"":text);j.put("value",value);HttpResult r=mobileRequest("POST","/v1/action",j.toString());if(r.code!=200)throw new Exception("AC3 addon HTTP "+r.code+": "+r.body);JSONObject o=new JSONObject(r.body);if(!o.optBoolean("ok",false))throw new Exception(o.optString("error","Action rejected"));runOnUiThread(()->{setBusy(false,"CONNECTED");toast(o.optString("result","Done"));loadControl(false);});}catch(Exception e){runOnUiThread(()->{setBusy(false,"CONNECTED");toast("Action failed: "+msg(e));});}});}
  private ParsedControl loadMobileState()throws Exception{HttpResult r=mobileRequest("GET","/v1/state",null);if(r.code!=200)throw new Exception("AC3 addon HTTP "+r.code);JSONObject o=new JSONObject(r.body);ParsedControl p=new ParsedControl();JSONObject m=o.optJSONObject("map");if(m!=null){p.mapName=m.optString("name","");p.mapAuthor=m.optString("author","");}p.secondsLeft=o.optInt("seconds_left",-1);p.paused=o.optBoolean("paused",false);JSONArray a=o.optJSONArray("players");if(a!=null)for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x==null)continue;String lg=x.optString("login","");String nn=x.optString("nickname",lg);p.players.add(new Player(lg,TmnfText.plain(nn),"",x.optBoolean("spectator",false)));}p.playerCount=p.players.size();return p;}
  private List<ChatLine> loadMobileChat()throws Exception{HttpResult r=mobileRequest("GET","/v1/chat?limit=120",null);if(r.code!=200)throw new Exception("chat HTTP "+r.code);JSONArray a=new JSONArray(r.body);ArrayList<ChatLine> out=new ArrayList<>();for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x==null)continue;ChatLine c=new ChatLine();c.sourceKey="AC3";c.login=x.optString("login","");c.nickname=x.optString("nickname",c.login);c.message=x.optString("message","");out.add(c);}return out;}
  private ArrayList<ConsoleLine> loadMobileConsole()throws Exception{HttpResult r=mobileRequest("GET","/v1/console?lines=100",null);ArrayList<ConsoleLine> out=new ArrayList<>();if(r.code!=200)return out;JSONArray a=new JSONArray(r.body);for(int i=0;i<a.length();i++){ConsoleLine c=new ConsoleLine();c.result=a.optString(i,"");out.add(c);}return out;}
  private HttpResult mobileRequest(String method,String path,String body)throws Exception{HttpsURLConnection c=(HttpsURLConnection)new URL(MOBILE_AC3+path).openConnection();c.setSSLSocketFactory(pinnedFactory());c.setHostnameVerifier((h,s)->"87.237.52.153".equals(h));c.setConnectTimeout(5000);c.setReadTimeout(7000);c.setRequestProperty("User-Agent","ArenaControl-Android/2.5");c.setRequestProperty("Accept","application/json");c.setRequestProperty("X-Arena-Mobile","1");c.setRequestProperty("X-Arena-Login",login);c.setRequestProperty("Cookie",websiteCookie());if("POST".equals(method)){c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json; charset=UTF-8");byte[] b=(body==null?"{}":body).getBytes(StandardCharsets.UTF_8);try(OutputStream o=c.getOutputStream()){o.write(b);}}int code=c.getResponseCode();InputStream in=code>=400?c.getErrorStream():c.getInputStream();String txt=in==null?"":new String(readAll(in),StandardCharsets.UTF_8);return new HttpResult(code,c.getURL().toString(),txt);}
  private String websiteCookie(){StringBuilder b=new StringBuilder();for(HttpCookie c:cookies.getCookieStore().getCookies()){if(b.length()>0)b.append("; ");b.append(c.getName()).append("=").append(c.getValue());}return b.toString();}
  private SSLSocketFactory pinnedFactory()throws Exception{TrustManager[] t={new X509TrustManager(){public X509Certificate[] getAcceptedIssuers(){return new X509Certificate[0];}public void checkClientTrusted(X509Certificate[] c,String a)throws CertificateException{}public void checkServerTrusted(X509Certificate[] chain,String auth)throws CertificateException{if(chain==null||chain.length==0)throw new CertificateException("No certificate");try{MessageDigest md=MessageDigest.getInstance("SHA-256");StringBuilder h=new StringBuilder();for(byte x:md.digest(chain[0].getEncoded()))h.append(String.format(Locale.ROOT,"%02x",x));if(!h.toString().equals(MOBILE_CERT_SHA256))throw new CertificateException("AC3 mobile certificate mismatch");}catch(CertificateException e){throw e;}catch(Exception e){throw new CertificateException(e);}}}};SSLContext sc=SSLContext.getInstance("TLS");sc.init(null,t,new SecureRandom());return sc.getSocketFactory();}

'''
